async def stream_to_ui(graph, request, thread_id):
    config={"configurable":{"thread_id":thread_id}}
    async for mode, chunk in graph.astream(request, config, stream_mode=["updates","custom"]):
        yield {"mode":mode,"data":chunk}
print("UI는 updates로 단계 상태를, custom으로 진행률을 갱신합니다.")
